import { db, ResponseTooLarge, type Db, type DbRow, type Param } from "./db";
import { HttpError } from "./errors";
import { coerce, describeErrors } from "./coerce";
import {
  authorize,
  availableTransitions,
  decideTransition,
  entityByTable,
  readScope,
  transitionInputProblems,
} from "./guard";
import { registry } from "./registry";
import type { Column, EntityDef, Row, User } from "./types";

type Change = { entityId: string; before: Row | null; after: Row | null };

const jsonb = (v: unknown) => (v === null ? null : JSON.stringify(v));

export async function withAudit<T>(
  actor: string,
  entity: EntityDef,
  action: string,
  change: (tx: Db) => Promise<Change & { result: T }>,
): Promise<T> {
  return db.begin(async (tx) => {
    const c = await change(tx);
    if (registry.audit.enabled)
      await tx.query(
        `insert into audit_events (actor, entity, entity_id, action, before, after)
        values ($1, $2, cast($3 as uuid), $4, cast($5 as jsonb), cast($6 as jsonb))`,
        [actor, entity.entity, c.entityId, action, jsonb(c.before), jsonb(c.after)],
      );
    return c.result;
  });
}

function resolve(table: string): EntityDef {
  const e = entityByTable(table);
  if (!e) throw new HttpError(404, `unknown entity '${table}'`);
  return e;
}

const plain = (row: DbRow): Row => JSON.parse(JSON.stringify(row)) as Row;

/** Registry names are validated snake_case, so quoting is all an identifier needs. */
const q = (name: string) => `"${name}"`;

const casts: Partial<Record<Column["input"], string>> = {
  int: "integer",
  decimal: "numeric",
  bool: "boolean",
  date: "date",
  datetime: "timestamptz",
  ref: "uuid",
};
const systemCasts: Record<string, string> = { updated_at: "timestamptz" };

/** Appends one bound parameter, cast to its column's type so both drivers send the same thing. */
function bind(entity: EntityDef, params: Param[], column: string, value: unknown): string {
  params.push(value as Param);
  const type = systemCasts[column] ?? casts[entity.columns.find((c) => c.name === column)?.input ?? "string"];
  return type ? `cast($${params.length} as ${type})` : `$${params.length}`;
}

async function load(tx: Db, entity: EntityDef, id: string, lock = false): Promise<Row | null> {
  if (!/^[0-9a-f-]{36}$/i.test(id)) return null;
  const rows = await tx.query(
    `select * from ${q(entity.table)} where id = cast($1 as uuid)${lock ? " for update" : ""}`,
    [id],
  );
  return rows[0] ? plain(rows[0]) : null;
}

const firstPage = 500;

/**
 * Reads every row of an ordered select, page by page in one snapshot. A page too big for the driver is retried
 * with half as many rows, so a large list comes back whole or fails loudly, never cut short.
 */
async function readAll(text: string, params: Param[], max = Infinity): Promise<Row[]> {
  for (let size = firstPage; ; size = Math.ceil(size / 2)) {
    try {
      return await db.begin(async (tx) => {
        await tx.query("set transaction isolation level repeatable read, read only");
        const rows: Row[] = [];
        for (;;) {
          const want = Math.min(size, max - rows.length);
          const page = await tx.query(`${text} limit ${want} offset ${rows.length}`, params);
          rows.push(...page.map(plain));
          if (page.length < want || rows.length >= max) return rows;
        }
      });
    } catch (e) {
      if (!(e instanceof ResponseTooLarge) || size === 1) throw e;
    }
  }
}

export async function list(user: User, table: string): Promise<Row[]> {
  const entity = resolve(table);
  const scope = readScope(user, entity);
  if (!scope) throw new HttpError(403, `cannot read ${entity.entity}`);
  return scope === "all"
    ? readAll(`select * from ${q(entity.table)} order by created_at desc, id`, [])
    : readAll(`select * from ${q(entity.table)} where created_by = $1 order by created_at desc, id`, [user.email]);
}

export async function get(user: User, table: string, id: string): Promise<Row> {
  const entity = resolve(table);
  const row = await load(db, entity, id);
  if (!row || !authorize(user, entity, "read", row)) throw new HttpError(404, "not found");
  return row;
}

function valuesOrThrow(entity: EntityDef, input: Record<string, unknown>, mode: "create" | "update" | "transition") {
  const r = coerce(entity, input, mode);
  if (!r.ok) throw new HttpError(422, describeErrors(r.errors), r.errors);
  return r.values;
}

export async function create(user: User, table: string, input: Record<string, unknown>): Promise<Row> {
  const entity = resolve(table);
  if (!authorize(user, entity, "create")) throw new HttpError(403, `cannot create ${entity.entity}`);
  const values = { ...valuesOrThrow(entity, input, "create"), created_by: user.email };
  return withAudit(user.email, entity, "create", async (tx) => {
    const params: Param[] = [];
    const cols = Object.keys(values);
    const placeholders = cols.map((c) => bind(entity, params, c, values[c as keyof typeof values]));
    const [row] = await tx.query(
      `insert into ${q(entity.table)} (${cols.map(q).join(", ")}) values (${placeholders.join(", ")}) returning *`,
      params,
    );
    const after = plain(row);
    return { entityId: after.id, before: null, after, result: after };
  });
}

function updateRow(tx: Db, entity: EntityDef, id: string, values: Record<string, unknown>) {
  const params: Param[] = [id];
  const set = Object.keys(values).map((c) => `${q(c)} = ${bind(entity, params, c, values[c])}`);
  return tx.query(`update ${q(entity.table)} set ${set.join(", ")} where id = cast($1 as uuid) returning *`, params);
}

export async function update(user: User, table: string, id: string, input: Record<string, unknown>): Promise<Row> {
  const entity = resolve(table);
  const values = valuesOrThrow(entity, input, "update");
  return withAudit(user.email, entity, "update", async (tx) => {
    const before = await load(tx, entity, id, true);
    if (!before || !authorize(user, entity, "read", before)) throw new HttpError(404, "not found");
    if (!authorize(user, entity, "update", before)) throw new HttpError(403, `cannot update this ${entity.entity}`);
    const [row] = await updateRow(tx, entity, id, { ...values, updated_at: new Date().toISOString() });
    const after = plain(row);
    return { entityId: id, before, after, result: after };
  });
}

export async function remove(user: User, table: string, id: string): Promise<void> {
  const entity = resolve(table);
  await withAudit(user.email, entity, "delete", async (tx) => {
    const before = await load(tx, entity, id, true);
    if (!before || !authorize(user, entity, "read", before)) throw new HttpError(404, "not found");
    if (!authorize(user, entity, "delete", before)) throw new HttpError(403, `cannot delete this ${entity.entity}`);
    await tx.query(`delete from ${q(entity.table)} where id = cast($1 as uuid)`, [id]);
    return { entityId: id, before, after: null, result: undefined };
  });
}

export async function transition(
  user: User,
  table: string,
  id: string,
  transitionId: string,
  input: Record<string, unknown> = {},
): Promise<Row> {
  const entity = resolve(table);
  const workflow = entity.workflow;
  if (!workflow?.transitions.some((t) => t.id === transitionId))
    throw new HttpError(404, `unknown transition '${transitionId}'`);
  const problems = transitionInputProblems(entity, transitionId, input);
  if (problems.length) throw new HttpError(422, problems.join("; "));
  const values = valuesOrThrow(entity, input, "transition");
  return withAudit(user.email, entity, `transition:${transitionId}`, async (tx) => {
    const before = await load(tx, entity, id, true);
    if (!before) throw new HttpError(404, "not found");
    const d = decideTransition(user, entity, before, transitionId, values);
    if (!d.ok) throw new HttpError(d.status, d.reason);
    const [row] = await updateRow(tx, entity, id, {
      ...values,
      [workflow.field]: d.transition.to,
      updated_at: new Date().toISOString(),
    });
    const after = plain(row);
    return { entityId: id, before, after, result: after };
  });
}

export async function requireTransition(user: User, table: string, id: string, transitionId: string): Promise<void> {
  const entity = resolve(table);
  if (!entity.workflow?.transitions.some((t) => t.id === transitionId))
    throw new HttpError(404, `unknown transition '${transitionId}'`);
  const row = await load(db, entity, id);
  if (!row || !authorize(user, entity, "read", row)) throw new HttpError(404, "not found");
}

export async function rowLabels(user: User, entity: EntityDef): Promise<Record<string, string>> {
  const rows = readScope(user, entity) ? await list(user, entity.table) : [];
  return Object.fromEntries(rows.map((r) => [r.id, String(r[entity.display] ?? r.id)]));
}

export async function refLabels(user: User, entity: EntityDef): Promise<Record<string, Record<string, string>>> {
  const out: Record<string, Record<string, string>> = {};
  for (const c of entity.columns) {
    const target = c.input === "ref" && c.ref ? entityByTable(c.ref) : undefined;
    if (!target) continue;
    out[c.name] = await rowLabels(user, target);
  }
  return out;
}

export async function inbox(user: User): Promise<{ entity: EntityDef; row: Row }[]> {
  const out: { entity: EntityDef; row: Row }[] = [];
  for (const entity of registry.entities) {
    if (!entity.workflow || !readScope(user, entity)) continue;
    for (const row of await list(user, entity.table))
      if (availableTransitions(user, entity, row).length) out.push({ entity, row });
  }
  return out;
}

export async function auditLog(user: User, limit = 200): Promise<Row[]> {
  if (!user.roles.includes("admin")) throw new HttpError(403, "the audit log is for admins");
  // id is bigserial: as text it keeps all 64 bits, and both drivers return the same string.
  return readAll(
    "select cast(id as text) as id, at, actor, entity, entity_id, action, before, after from audit_events order by audit_events.id desc",
    [],
    limit,
  );
}
